insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000417481', '40000000-0000-4000-8000-000000041748', 'Examine os quadrados', 'As parcelas que dependem de x e y nunca são negativas.', 1), ('70000000-0000-4000-8000-000000417482', '40000000-0000-4000-8000-000000041748', 'Encontre o vértice', '$x=0 e y=0 fornecem z=0.$', 2), ('70000000-0000-4000-8000-000000417483', '40000000-0000-4000-8000-000000041748', 'Conclua', 'As seções horizontais crescem como elipses; a superfície abre no sentido positivo de z.', 3)
